/**
 * MCP resources: read-only documents under factlot:// that an agent can read without a key and
 * without a registry lookup. Every figure comes from RESOURCE_DATA (resource-data.ts, generated by
 * scripts/mcp/gen-resources.ts from site/_data/hosted.json and the other files it names) or from
 * the code itself (the tool catalog, the fact schemas); nothing here states a count of its own.
 *
 *   factlot://coverage                  what the hosted registry serves, by place
 *   factlot://coverage/{place}          one place: counties, parcels, as-of dates, roll years, sources
 *   factlot://sources                   the reviewed source catalog (index)
 *   factlot://sources/{source_id}       one source: publisher, licence, AI use, redistribution, attribution
 *   factlot://markets                   the hosted places with a worked example (index)
 *   factlot://markets/{slug}            one place's worked example: the calls, what they returned, the terms
 *   factlot://schemas/fact              the fact model as JSON Schema
 *   factlot://schemas/tools             the tool list (index)
 *   factlot://schemas/tools/{tool}      one tool's input JSON Schema
 *   factlot://spec/id                   the FactLot ID specification (Markdown)
 *   factlot://plans                     plans and how registry lookups are counted
 */
import { ID_SPEC_VERSION } from "@factlot/id";
import { jsonSchemas } from "@factlot/schema";
import {
  type McpServer,
  ResourceTemplate,
} from "@modelcontextprotocol/sdk/server/mcp.js";
import {
  McpError,
  type ReadResourceResult,
} from "@modelcontextprotocol/sdk/types.js";

import { RESOURCE_DATA } from "./resource-data.ts";
import { catalogSourceId } from "./source-ids.ts";

export { catalogSourceId };

// --- The generated data's shape ------------------------------------------------------------------

export interface HostedCounty {
  fips: string;
  name: string;
  state: string;
  parcels: number;
  buildings: number;
  as_of: string;
  sources: string[];
}

export interface HostedPlace {
  key: string;
  counties: string[];
  names: string[];
  parcels: number;
  buildings: number;
  as_of: string;
}

/** site/_data/hosted.json as written by scripts/site/gen-hosted.ts. */
export interface HostedData {
  about: string;
  pack_built_at: string;
  totals: {
    parcels: number;
    counties: number;
    buildings: number;
    entities: number;
    states: string[];
  };
  places: HostedPlace[];
  counties: HostedCounty[];
  texas_order: string[];
  entity_registries: {
    jurisdiction: string;
    entities: number;
    total?: number;
  }[];
  withheld: { fips: string; name: string; state: string }[];
  partial: { fips: string; area: string }[];
  text?: { places: string; totals: string; withheld: string };
}

export interface MarketSource {
  source_id: string;
  publisher: string;
  title: string;
  url: string;
  license: string;
  ai_use: string;
  redistribution: string;
  attribution: string | null;
  terms_reviewed: string;
}

/** One entry of site/_data/markets.json with its page facts from scripts/site/market-pages.mjs. */
export interface MarketEntry {
  slug: string;
  place: string;
  name: string;
  id_name: string;
  id_text: string;
  entity: { jurisdiction: string; name: string } | null;
  limits: string[];
  notices: string[];
  id_system: string;
  sources: MarketSource[];
  sample: {
    query: string;
    matches: number;
    urn: string;
    label: string;
    external_id: string;
    tax_year: number | null;
    market_value: number | null;
    appraised_value: number | null;
    predicates: string[];
  };
  holds: { owner_of_record: boolean; zoning: boolean };
}

/** One reviewed source, from its config in registry/sources/. */
export interface SourceEntry {
  source_id: string;
  state: string;
  publisher: string;
  status: "verified" | "gated" | "not verified";
  license: string | null;
  ai_use: string | null;
  redistribution: string | null;
  attribution: string | null;
  terms_url: string | null;
  reviewed: string | null;
  review_record: string;
  config: string;
  /** FIPS codes of the hosted counties whose facts cite this source. */
  hosted_counties: string[];
}

/** Plan facts from deploy/cloudflare/src/plans.ts. */
export interface PlanFacts {
  pricing_url: string;
  free: {
    requests_per_minute: number;
    registry_lookups_per_day: number;
    reports_per_month: number;
  };
  paid: {
    id: string;
    name: string;
    usd_per_month: number;
    usd_per_year?: number;
    requests_per_minute: number;
    registry_lookups_per_month: number;
    keys: number;
    reports_per_month: number;
    summary: string;
  }[];
  gating: {
    free_history: string;
    batch: string;
    dated_get: string;
    /** Everything that needs a Pro or Team key on the hosted API (PAID_ONLY in plans.ts). */
    paid_only: { what: string; free: string; tools: string[]; arg?: string }[];
  };
  quota_rules: Record<string, string>;
}

export interface ResourceData {
  hosted: HostedData;
  /** Roll years each hosted Texas county holds, by county FIPS (site/_data/texas-counties.json). */
  roll_years: Record<string, { tax_year: number; preliminary: boolean }[]>;
  markets: MarketEntry[];
  sources: SourceEntry[];
  id_spec: string;
  plans: PlanFacts;
}

// --- Where this server stands --------------------------------------------------------------------

/** What the server that serves the resources is. */
export interface ResourceContext {
  /** The hosted FactLot service (api.factlot.com), which answers from the pack hosted.json describes. */
  hosted: boolean;
  /** registry_* tools are registered on this server. */
  registry: boolean;
  /** The local-only tools are registered (the stdio server). */
  localFiles: boolean;
}

export const HOSTED_MCP_URL = "https://api.factlot.com/mcp";
const SITE = "https://factlot.com";
const REPO = "https://github.com/9mp96ygnbk-alt/factlot/blob/main";
/** JSON-RPC error for a resource that does not exist (MCP specification, resources). */
export const RESOURCE_NOT_FOUND = -32002;

