/** The markets whose place the hosted pack serves (the site gives no page to any other). */
export function hostedMarkets(data: ResourceData): MarketEntry[] {
  return data.markets.filter((m) =>
    data.hosted.places.some((p) => p.key === m.place),
  );
}

function placeName(data: ResourceData, place: HostedPlace): string {
  const market = data.markets.find((m) => m.place === place.key);
  if (market) return market.name[0]!.toUpperCase() + market.name.slice(1);
  const code = data.hosted.counties.find(
    (c) => c.fips === place.counties[0],
  )?.state;
  const state = code ? STATE_NAMES[code]?.replace(/^the /, "") : undefined;
  if (!state) return place.key;
  // A place of a few counties is named by them (Juab County and Summit County, Utah).
  if (place.names.length > 3 || place.names.every((n) => n === state))
    return state;
  const names =
    place.names.length === 1
      ? place.names[0]!
      : `${place.names.slice(0, -1).join(", ")} and ${place.names.at(-1)}`;
  return `${names}, ${state}`;
}

/** Where the coverage figures stand relative to this server, in one paragraph. */
export function coverageStanding(data: ResourceData, ctx: ResourceContext) {
  const built = data.hosted.pack_built_at;
  if (ctx.hosted)
    return {
      this_server: "hosted",
      note: `This server is the hosted FactLot service (${HOSTED_MCP_URL}). These are the regions it answers registry_* tools for, from the registry pack built ${built}. registry_coverage gives the same live, with the ID systems and every source's as-of date, and is never metered.`,
    };
  return {
    this_server: ctx.registry ? "self-hosted with a registry file" : "local",
    note: `This is what the hosted FactLot service (${HOSTED_MCP_URL}) served in the registry pack built ${built}, as recorded when this package was built; it is not what this server holds. ${
      ctx.registry
        ? "This server answers registry_* tools from its own registry file: call registry_coverage here for what that file holds."
        : "This server has no registry loaded, so it lists no registry_* tools (set FACTLOT_REGISTRY_DB to a registry file to add them)."
    } For the hosted service's live coverage, call registry_coverage on ${HOSTED_MCP_URL}; it is never metered.`,
  };
}

function valueHistoryNote(data: ResourceData) {
  return `registry_get's value_history lists market and appraised value by tax year, each cited. roll_years gives the roll years held for each hosted Texas county; for other places the record itself shows the years held. On the hosted API, when paid gating is on (GET https://api.factlot.com/v1/plans shows it), a call without a Pro or Team key gets the ${data.plans.gating.free_history} in value_history and history; a Pro or Team key gets every year. See factlot://plans.`;
}

export function coverageResource(data: ResourceData, ctx: ResourceContext) {
  const h = data.hosted;
  return {
    uri: "factlot://coverage",
    ...coverageStanding(data, ctx),
    pack_built_at: h.pack_built_at,
    summary: h.text
      ? `Hosted registry: ${h.text.places}; ${h.text.totals}. ${h.text.withheld}`.trim()
      : undefined,
    totals: h.totals,
    places: h.places.map((p) => ({
      key: p.key,
      name: placeName(data, p),
      uri: `factlot://coverage/${p.key}`,
      parcels: p.parcels,
      buildings: p.buildings,
      as_of: p.as_of,
      counties: p.counties.length,
      ...(hostedMarkets(data).some((m) => m.place === p.key)
        ? {
            market: `factlot://markets/${
              data.markets.find((m) => m.place === p.key)!.slug
            }`,
          }
        : {}),
    })),
    entity_registries: h.entity_registries,
    withheld: h.withheld,
    partial: h.partial,
    value_history: valueHistoryNote(data),
    misses:
      "A lookup outside these regions is a coverage miss (not loaded), not a sign that the parcel or entity does not exist; misses are not counted as lookups.",
  };
}

export function placeResource(
  data: ResourceData,
  ctx: ResourceContext,
  key: string,
) {
  const p = data.hosted.places.find((x) => x.key === key);
  if (!p) return undefined;
  const counties = data.hosted.counties.filter((c) =>
    p.counties.includes(c.fips),
  );
  const market = hostedMarkets(data).find((m) => m.place === p.key);
  return {
    uri: `factlot://coverage/${p.key}`,
    name: placeName(data, p),
    ...coverageStanding(data, ctx),
    pack_built_at: data.hosted.pack_built_at,
    parcels: p.parcels,
    buildings: p.buildings,
    as_of: p.as_of,
    counties: counties.map((c) => {
      const rolls = data.roll_years[c.fips];
      return {
        fips: c.fips,
        name: c.name,
        state: c.state,
        parcels: c.parcels,
        buildings: c.buildings,
        as_of: c.as_of,
        roll_years: rolls ?? null,
        ...(rolls ? { value_history: rolls.length > 1 } : {}),
        partial:
          data.hosted.partial.find((x) => x.fips === c.fips)?.area ?? null,
        sources: c.sources.map((s) => {
          const id = catalogSourceId(
            data.sources.map((x) => x.source_id),
            s,
          );
          return { source_id: s, uri: id ? `factlot://sources/${id}` : null };
        }),
      };
    }),
    withheld: data.hosted.withheld.filter(
      (w) => w.state === counties[0]?.state,
    ),
    ...(market ? { market: `factlot://markets/${market.slug}` } : {}),
    value_history: valueHistoryNote(data),
  };
}

export function sourcesIndex(data: ResourceData) {
  const count = (s: SourceEntry["status"]) =>
    data.sources.filter((x) => x.status === s).length;
  return {
    uri: "factlot://sources",
    about:
      "Every public-record source FactLot has reviewed, from the source configs in registry/sources/. Read factlot://sources/{source_id} for one source's publisher, licence, AI use, redistribution and attribution as recorded. This is a record of what each publisher says as the reviewer read it on the date shown; it is not legal advice and grants no right. hosted: facts from the source are served by the hosted registry.",
    rights_table: `${REPO}/docs/registry/rights.md`,
    sources_total: data.sources.length,
    verified: count("verified"),
    gated: count("gated"),
    not_verified: count("not verified"),
    sources: data.sources.map((s) => ({
      source_id: s.source_id,
      state: s.state,
      publisher: s.publisher,
      status: s.status,
      hosted: s.hosted_counties.length > 0,
      uri: `factlot://sources/${s.source_id}`,
    })),
  };
}

export function sourceResource(data: ResourceData, id: string) {
  const s = data.sources.find((x) => x.source_id === id);
  if (!s) return undefined;
  const { hosted_counties, ...rest } = s;
  return {
    uri: `factlot://sources/${s.source_id}`,
    ...rest,
    hosted_counties: data.hosted.counties
      .filter((c) => hosted_counties.includes(c.fips))
      .map((c) => ({ fips: c.fips, name: c.name, state: c.state })),
    note: "As recorded by FactLot's reviewer on the reviewed date; not legal advice and not a grant of any right. Each registry fact carries its source snapshot's licence, ai_use, redistribution and attribution: relay them with the fact. status verified: the terms were reviewed and the file URLs confirmed by a download; gated: nothing is collected until a person clears the named gate.",
  };
}

export function marketsIndex(data: ResourceData) {
  return {
    uri: "factlot://markets",
    about:
      "Hosted places with a worked example: the calls an agent makes there, what they returned when the example was generated, the ID system, the sources' recorded terms and what the place does not hold. Texas has its own pages at https://factlot.com/texas/.",
    markets: hostedMarkets(data).map((m) => ({
      slug: m.slug,
      name: m.name[0]!.toUpperCase() + m.name.slice(1),
      uri: `factlot://markets/${m.slug}`,
      page: `${SITE}/${m.slug}/`,
    })),
  };
}

export function marketResource(data: ResourceData, slug: string) {
  const m = hostedMarkets(data).find((x) => x.slug === slug);
  if (!m) return undefined;
  const p = data.hosted.places.find((x) => x.key === m.place)!;
  const reg = m.entity
    ? data.hosted.entity_registries.find(
        (r) => r.jurisdiction === m.entity!.jurisdiction,
      )
    : undefined;
  const s = m.sample;
  const calls: Record<string, unknown>[] = [
    {
      tool: "registry_search_address",
      arguments: { query: s.query },
      returned: { matches: s.matches, first: { urn: s.urn, label: s.label } },
    },
    {
      tool: "registry_get",
      arguments: { urn: s.urn },
      returned: {
        tax_year: s.tax_year,
        market_value: s.market_value,
        appraised_value: s.appraised_value,
        predicates: s.predicates,
      },
    },
    {
      tool: "registry_resolve_external",
      arguments: { system: m.id_system, external_id: s.external_id },
      returned: { urn: s.urn },
    },
  ];
  if (m.holds.owner_of_record)
    calls.push({
      tool: "registry_search_entities",
      then: "registry_owned_by",
      note: "Organisation owners and the parcels linked to them; natural persons are never returned.",
    });
  return {
    uri: `factlot://markets/${m.slug}`,
    name: m.name[0]!.toUpperCase() + m.name.slice(1),
    page: `${SITE}/${m.slug}/`,
    coverage: `factlot://coverage/${p.key}`,
    hosted: {
      parcels: p.parcels,
      buildings: p.buildings,
      as_of: p.as_of,
      counties: p.counties,
      entity_registry:
        m.entity && reg
          ? {
              name: m.entity.name,
              jurisdiction: m.entity.jurisdiction,
              entities: reg.entities,
              ...(reg.total !== undefined ? { total: reg.total } : {}),
            }
          : null,
    },
    id_system: { system: m.id_system, name: m.id_name, text: m.id_text },
    sources: m.sources.map((x) => ({
      ...x,
      uri: `factlot://sources/${x.source_id}`,
    })),
    example: {
      note: "What the tools answered when this example was generated; a call now answers from the current pack and may differ. A registry call that finds something is one registry lookup; calls that find nothing (up to an hourly limit), registry_coverage, coverage misses and input errors are not counted.",
      calls,
    },
    holds: m.holds,
    limits: [
      ...(m.holds.owner_of_record
        ? [
            "Owners that are natural persons are never returned; a parcel whose owner is a person shows no owner.",
          ]
        : []),
      ...m.limits,
      "Commercial, industrial and multifamily parcels only; a residential or exempt parcel is a coverage miss, not a sign the parcel does not exist.",
    ],
    notices: m.notices,
  };
}

/** A tool as this server registers it, for the tool index (createServer builds the list). */
export interface ListedTool {
  name: string;
  title: string;
  description: string;
  rest_path: string | null;
  formula: string | null;
  requires: "registry" | "local machine" | null;
  /** The input JSON Schema, built on first read only. */
  inputSchema: () => Record<string, unknown>;
}

interface ToolEntry extends Omit<ListedTool, "inputSchema"> {
  input_schema: Record<string, unknown>;
}

/**
 * The tool entries of one server configuration, built once per isolate: the hosted API builds a
 * server per request, and turning every tool's input into JSON Schema on each read is costly.
 */
const toolEntryCache = new Map<string, ToolEntry[]>();

const contextKey = (ctx: ResourceContext) =>
  `${ctx.hosted}|${ctx.registry}|${ctx.localFiles}`;

function toolEntries(
  ctx: ResourceContext,
  listed: readonly ListedTool[],
): ToolEntry[] {
  const key = contextKey(ctx);
  let entries = toolEntryCache.get(key);
  if (!entries) {
    entries = listed.map(({ inputSchema, ...t }) => ({
      ...t,
      input_schema: inputSchema(),
    }));
    toolEntryCache.set(key, entries);
  }
  return entries;
}

export function toolsIndex(
  ctx: ResourceContext,
  listed: readonly ListedTool[],
) {
  return {
    uri: "factlot://schemas/tools",
    about: `The tools this server lists in tools/list, with REST path and formula where they have one; factlot://schemas/tools/{tool} gives one tool's input JSON Schema as the server validates it. requires registry: the tool answers from a FactLot Registry, and is listed only on a server that has one.${
      ctx.hosted
        ? " The hosted service adds tools of its own to tools/list for some callers (report_create, the account tools with a key, the model-backed tools); their entries are marked hosted_extra and carry their input schema here."
        : ""
    } The facts tools return are described by factlot://schemas/fact.`,
    tools: listed.map((t) => ({
      name: t.name,
      title: t.title,
      rest_path: t.rest_path,
      formula: t.formula,
      requires: t.requires,
      uri: `factlot://schemas/tools/${t.name}`,
    })),
  };
}

export function toolResource(
  ctx: ResourceContext,
  listed: readonly ListedTool[],
  name: string,
) {
  const t = toolEntries(ctx, listed).find((x) => x.name === name);
  return t ? { uri: `factlot://schemas/tools/${t.name}`, ...t } : undefined;
}

export function plansResource(data: ResourceData) {
  const p = data.plans;
  return {
    uri: "factlot://plans",
    about:
      "Plans of the hosted API (https://api.factlot.com), as GET /v1/plans states them. Every calculator, ID, fact, rules and document tool is on every plan; registry lookups are metered. Reading these resources and prompts uses no registry lookup and needs no key.",
    pricing: p.pricing_url,
    free: p.free,
    paid: p.paid,
    paid_gating: {
      note: "When paid gating is on (GET https://api.factlot.com/v1/plans shows it as gating), these need a Pro or Team key; a call without one says so and links the pricing page.",
      value_history_without_key: p.gating.free_history,
      registry_batch: p.gating.batch,
      dated_registry_get: p.gating.dated_get,
      paid_only: p.gating.paid_only,
    },
    quota_rules: p.quota_rules,
  };
}

// --- Registration ----------------------------------------------------------------------------------

function jsonResult(uri: URL, body: unknown): ReadResourceResult {
  return {
    contents: [
      {
        uri: uri.href,
        mimeType: "application/json",
        text: JSON.stringify(body, null, 2),
      },
    ],
  };
}

function notFound(uri: URL, hint: string): McpError {
  // A URI can be as long as the request allows: name at most its first 200 characters.
  const shown =
    uri.href.length > 200 ? `${uri.href.slice(0, 200)}...` : uri.href;
  return new McpError(
    RESOURCE_NOT_FOUND,
    `Resource ${shown} not found: ${hint}`,
    { uri: shown },
  );
}

const one = (v: string | string[] | undefined) =>
  Array.isArray(v) ? (v[0] ?? "") : (v ?? "");

const prefixed = (values: string[], value: string) =>
  values.filter((v) => v.startsWith(value)).slice(0, 100);

type Completer = (value: string) => string[];

/**
 * A template's completion callbacks with no prototype: the SDK looks a callback up by the
 * argument name the client sends, so "toString" or "__proto__" must find nothing.
 */
function completers(
  entries: Record<string, Completer>,
): Record<string, Completer> {
  const out = Object.create(null) as Record<string, Completer>;
  for (const [k, f] of Object.entries(entries)) out[k] = f;
  return out;
}

/** Register every factlot:// resource and resource template on `server`. */
export function registerResources(
  server: McpServer,
  ctx: ResourceContext,
  listed: readonly ListedTool[],
  data: ResourceData = RESOURCE_DATA,
): void {
  const json = (
    name: string,
    uri: string,
    title: string,
    description: string,
    body: () => unknown,
  ) =>
    server.registerResource(
      name,
      uri,
      { title, description, mimeType: "application/json" },
      (u) => jsonResult(u, body()),
    );

  json(
    "coverage",
    "factlot://coverage",
    "Hosted registry coverage",
    "What the hosted FactLot registry serves, by place: counties, parcel and building counts, as-of dates, entity registries, what is withheld, and how value history works. No lookup is used.",
    () => coverageResource(data, ctx),
  );
  server.registerResource(
    "coverage-place",
    new ResourceTemplate("factlot://coverage/{place}", {
      list: () => ({
        resources: data.hosted.places.map((p) => ({
          uri: `factlot://coverage/${p.key}`,
          name: `coverage-${p.key}`,
          title: `Coverage: ${placeName(data, p)}`,
          mimeType: "application/json",
        })),
      }),
      complete: completers({
        place: (v) =>
          prefixed(
            data.hosted.places.map((p) => p.key),
            v,
          ),
      }),
    }),
    {
      title: "Hosted coverage of one place",
      description:
        "One hosted place: each county with its parcels, buildings, as-of date, roll years (Texas) and sources.",
      mimeType: "application/json",
    },
    (uri, vars) => {
      const body = placeResource(data, ctx, one(vars.place));
      if (!body)
        throw notFound(
          uri,
          "the places are listed in factlot://coverage (keys such as tx)",
        );
      return jsonResult(uri, body);
    },
  );

  json(
    "sources",
    "factlot://sources",
    "Source catalog",
    "Every reviewed public-record source: publisher, state, review status and whether the hosted registry serves it. Each source's recorded terms are at factlot://sources/{source_id}.",
    () => sourcesIndex(data),
  );
  server.registerResource(
    "source",
    new ResourceTemplate("factlot://sources/{source_id}", {
      // Listed in factlot://sources rather than in resources/list, which stays short.
      list: undefined,
      complete: completers({
        source_id: (v) =>
          prefixed(
            data.sources.map((s) => s.source_id),
            v,
          ),
      }),
    }),
    {
      title: "One source and its recorded rights",
      description:
        "One reviewed source: publisher, licence, AI use, redistribution, attribution, terms URL, review date and status, and the hosted counties whose facts cite it.",
      mimeType: "application/json",
    },
    (uri, vars) => {
      const body = sourceResource(data, one(vars.source_id));
      if (!body)
        throw notFound(uri, "the source ids are listed in factlot://sources");
      return jsonResult(uri, body);
    },
  );

  json(
    "markets",
    "factlot://markets",
    "Worked examples by market",
    "The hosted places with a worked example of the registry calls, the sources' terms and what each place does not hold.",
    () => marketsIndex(data),
  );
  server.registerResource(
    "market",
    new ResourceTemplate("factlot://markets/{slug}", {
      list: () => ({
        resources: hostedMarkets(data).map((m) => ({
          uri: `factlot://markets/${m.slug}`,
          name: `market-${m.slug}`,
          title: `Worked example: ${m.name[0]!.toUpperCase()}${m.name.slice(1)}`,
          mimeType: "application/json",
        })),
      }),
      complete: completers({
        slug: (v) =>
          prefixed(
            hostedMarkets(data).map((m) => m.slug),
            v,
          ),
      }),
    }),
    {
      title: "Worked example for one market",
      description:
        "One hosted place: the example calls and what they returned, the ID system, the sources' recorded terms, limits and notices.",
      mimeType: "application/json",
    },
    (uri, vars) => {
      const body = marketResource(data, one(vars.slug));
      if (!body)
        throw notFound(
          uri,
          "the hosted markets are listed in factlot://markets",
        );
      return jsonResult(uri, body);
    },
  );

  json(
    "fact-schema",
    "factlot://schemas/fact",
    "FactLot fact model (JSON Schema)",
    "Fact, Provenance, SourceRef, Rights and Relationship as JSON Schema, the same as the schema_get tool.",
    () => jsonSchemas(),
  );
  json(
    "tool-schemas",
    "factlot://schemas/tools",
    "Tool list",
    "Every FactLot tool with its REST path and formula; factlot://schemas/tools/{tool} gives its input JSON Schema.",
    () => toolsIndex(ctx, listed),
  );
  server.registerResource(
    "tool-schema",
    new ResourceTemplate("factlot://schemas/tools/{tool}", {
      list: undefined,
      complete: completers({
        tool: (v) =>
          prefixed(
            listed.map((t) => t.name),
            v,
          ),
      }),
    }),
    {
      title: "One tool's input schema",
      description:
        "One tool's title, description, REST path, formula and input JSON Schema.",
      mimeType: "application/json",
    },
    (uri, vars) => {
      const body = toolResource(ctx, listed, one(vars.tool));
      if (!body)
        throw notFound(
          uri,
          "the tool names are listed in factlot://schemas/tools",
        );
      return jsonResult(uri, body);
    },
  );

  server.registerResource(
    "id-spec",
    "factlot://spec/id",
    {
      title: `FactLot ID specification (v${ID_SPEC_VERSION})`,
      description:
        "URN and short-ID forms for parcels, entities, buildings, spaces, documents, leases and loans, and how each natural key is normalised (docs/id-spec.md). The id_* tools compute them.",
      mimeType: "text/markdown",
    },
    (uri) => ({
      contents: [
        { uri: uri.href, mimeType: "text/markdown", text: data.id_spec },
      ],
    }),
  );

  json(
    "plans",
    "factlot://plans",
    "Plans and lookup counting",
    "The hosted plans' allowances and prices, what a Pro or Team key adds when paid gating is on, and how registry lookups are counted.",
    () => plansResource(data),
  );
}
